package _pure.plan.root;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Stream;
import org.finos.legend.engine.plan.dependencies.store.shared.IExecutionNodeContext;
import org.finos.legend.engine.plan.dependencies.util.Library;

public class Execute
{
    public static long execute(IExecutionNodeContext context)
    {
        try
        {
            return Arrays.asList(1L, 1L).stream().reduce(0L, Library::integerPlus).longValue();
        }
        catch (Exception e)
        {
            throw new RuntimeException("Failed in node: root", e);
        }
    }
}
